ex:{
// --- Trapez ---
"Dumbbell Shrug":{n:"Slijeganje ramenima s bučicama",eq:"Bučice",what:"Izolira gornji trapez podizanjem ramena ravno gore uz opterećenje.",steps:["Stani uspravno s teškom bučicom u svakoj ruci, ruke ispružene uz tijelo.","Podigni ramena ravno prema ušima što više možeš.","Zadrži jednu sekundu na vrhu i stisni.","Polako spusti dok ne osjetiš puno istezanje trapeza."],cues:["Misli „ramena prema ušima”, ne „ramena natrag”","Laktovi ostaju ispruženi; ruke su samo kuke"],miss:["Kruženje ramenima","Poskakivanje s teškim teretom kroz mali opseg","Guranje brade naprijed"],rx:"3 × 10–15 · odmor 60–90 s"},
"Face Pull":{n:"Face pull (povlačenje sajle prema licu)",eq:"Sajla",what:"Trenira srednji i donji trapez zajedno sa stražnjim deltoidima i rotatornom manšetom. Osnova za zdravlje ramena i držanje.",steps:["Postavi uže na sajlu u visini lica.","Uhvati uže s palčevima okrenutima prema natrag i odmakni se dok ruke ne budu ispružene.","Povuci uže prema licu, razdvajajući krajeve pokraj ušiju.","Završi s laktovima visoko i šakama zarotiranima natrag, kao u pozi dvostrukog bicepsa.","Vrati se kontrolirano."],cues:["Vodi laktovima, a zatim zarotiraj šake natrag","Na kraju stisni lopatice"],miss:["Zabacivanje tijela i korištenje vlastite težine","Preteško opterećenje zbog kojeg laktovi padnu ispod šaka"],rx:"3 × 12–20 · odmor 60 s"},
"Farmer's Carry":{n:"Farmerski hod",eq:"Bučice / kettlebell",what:"Hodanje s teretom. Trapez drži ramena gore protiv težine, a hvat i trup također rade punom snagom.",steps:["Podigni težak teret u svaku ruku do uspravnog stava.","Stani uspravno: prsa gore, ramena lagano podignuta i povučena natrag.","Hodaj kratkim, kontroliranim koracima zadanu udaljenost.","Spusti teret ravnih leđa."],cues:["Hodaj kao da na glavi nosiš knjigu","Teret ne dodiruje noge"],miss:["Ramena padaju naprijed i dolje","Naginjanje na jednu stranu"],rx:"3–4 × 30–40 m · odmor 90 s"},
"Prone Y-Raise":{n:"Y-podizanje na kosoj klupi",eq:"Bučice + kosa klupa",what:"Ležanje prsima na kosoj klupi izolira donji trapez, koji rotira lopaticu prema gore za rad iznad glave.",steps:["Lezi prsima na klupu nagnutu oko 30–45°, s laganim bučicama ispod sebe.","Okreni palčeve prema stropu.","Podigni ruke naprijed i u stranu u oblik slova Y dok ne budu u liniji s tijelom.","Zadrži, pa polako spusti."],cues:["Zamisli da lopatice povlačiš dolje prema stražnjim džepovima","Vrlo lagane bučice ili isprva bez njih"],miss:["Podizanje ramena prema ušima","Izvijanje donjih leđa s klupe"],rx:"3 × 10–15 · odmor 45–60 s"},
"Rack Pull":{n:"Mrtvo dizanje iz stalka (rack pull)",eq:"Šipka + stalak",what:"Mrtvo dizanje s visine koljena. Omogućuje vrlo teška opterećenja koja grade gornji dio leđa i trapez.",steps:["Postavi osigurače ili blokove tako da šipka bude malo ispod ili iznad koljena.","Uhvati šipku tik izvan nogu, ravnih leđa, prsa gore, ramena iznad šipke.","Gurni kukove naprijed i uspravi se, na vrhu lagano povuci ramena natrag.","Kontrolirano vrati šipku na osigurače."],cues:["Napni trup prije svakog ponavljanja","Šipka ostaje uz bedra"],miss:["Jako zabacivanje na vrhu","Zaobljavanje gornjih leđa pri završetku"],rx:"3–4 × 5–8 · odmor 2–3 min"},
"Band Pull-Apart":{n:"Razvlačenje gume",eq:"Elastična guma",what:"Brza, lagana vježba za srednji trapez, romboide i stražnje deltoide. Dobra za zagrijavanje ili protiv sjedilačkog držanja.",steps:["Drži gumu ispred sebe u visini ramena, ruke ispružene, šake u širini ramena.","Razvuci gumu pomicanjem ruku u stranu.","Stani kad guma dotakne prsa i stisni lopatice.","Polako se vrati."],cues:["Ruke ostaju ispružene","Rebra dolje; ne izvijaj leđa na kraju"],miss:["Podizanje ramena","Savijanje laktova kao u veslanju"],rx:"2–3 × 15–25 · odmor 30–45 s"},
// --- Deltoidi ---
"Standing Overhead Press":{n:"Potisak šipke iznad glave iz stoja",eq:"Šipka",what:"Glavna vježba snage za prednji i bočni deltoid, uz pomoć tricepsa i gornjeg trapeza. Traži i čvrsto napet trup.",steps:["Postavi šipku u visinu gornjeg dijela prsa i uhvati je tik izvan širine ramena.","Skini šipku tako da leži na prednjim deltoidima, laktovi malo ispred šipke.","Napni trbuh i stisni gluteuse.","Potisni ravno gore, lagano pomičući glavu natrag da šipka prođe pokraj brade.","Kad šipka prođe glavu, gurni glavu naprijed, zaključaj ruke iznad sredine stopala pa spusti na prsa."],cues:["Zapešća iznad laktova","Rebra dolje, bez izvijanja donjih leđa"],miss:["Zabacivanje unatrag koje vježbu pretvara u kosi potisak","Potiskivanje šipke naprijed umjesto ravno gore"],rx:"Snaga 4 × 4–6 · Masa 3 × 8–10 · odmor 2–3 min"},
"Dumbbell Lateral Raise":{n:"Odručenje s bučicama",eq:"Bučice",what:"Izolira bočni deltoid, glavu koja ramenima daje širinu.",steps:["Stani s laganim bučicama uz tijelo i laktovima lagano savijenima.","Podigni ruke u stranu do visine ramena.","Vodi laktovima, mali prst otprilike u razini palca.","Spuštaj 2–3 sekunde."],cues:["Guraj bučice prema zidovima, ne prema stropu","Odaberi težinu koju podižeš bez zamaha"],miss:["Slijeganje ramenima na početku pokreta","Zamah trupom"],rx:"3–4 × 12–20 · odmor 60 s"},
"Lateral Raise":{n:"Odručenje s bučicama",eq:"Bučice",what:"Izolira bočni deltoid, glavu koja ramenima daje širinu.",steps:["Stani s laganim bučicama uz tijelo i laktovima lagano savijenima.","Podigni ruke u stranu do visine ramena.","Vodi laktovima, mali prst otprilike u razini palca.","Spuštaj 2–3 sekunde."],cues:["Guraj bučice prema zidovima, ne prema stropu","Odaberi težinu koju podižeš bez zamaha"],miss:["Slijeganje ramenima na početku pokreta","Zamah trupom"],rx:"3–4 × 12–20 · odmor 60 s"},
"Reverse Dumbbell Fly":{n:"Obrnuto razvlačenje s bučicama",eq:"Bučice",what:"Cilja stražnji deltoid, koji je obično slabije treniran od prednjeg. Radi i srednji dio leđa.",steps:["Pregni se u kukovima dok trup nije gotovo paralelan s podom, ravnih leđa.","Pusti lagane bučice da vise ispod prsa, dlanovi okrenuti jedan prema drugom.","Podigni ruke široko u luku dok ne budu u liniji s trupom.","Zadrži, pa polako spusti."],cues:["Laktovi lagano i stalno savijeni","Posegni u širinu umjesto stiskanja lopatica"],miss:["Preteško, pa vježba postaje veslanje","Uspravljanje iz pretklona kako se umaraš"],rx:"3 × 12–20 · odmor 60 s"},
"Seated Dumbbell Shoulder Press":{n:"Potisak bučica iznad glave iz sjeda",eq:"Bučice + klupa",what:"Potisak iznad glave s naslonom. Naslon rasterećuje trup pa deltoidi mogu raditi jače.",steps:["Postavi klupu uspravno i sjedni naslonjen leđima.","Dovedi bučice u visinu ramena, dlanovi naprijed, laktovi malo ispred tijela.","Potisni gore dok ruke nisu ispružene iznad glave.","Spusti otprilike do visine ušiju."],cues:["Podlaktice ostaju okomite","Donja leđa ostaju uz naslon"],miss:["Odvajanje leđa od naslona","Spuštanje samo do pola"],rx:"3 × 8–12 · odmor 90 s"},
"Pike Push-Up":{n:"Pike sklek",eq:"Vlastita težina",what:"Sklek s visoko podignutim kukovima, pa vlastitu težinu potiskuješ iznad glave. Most prema sklekovima u stoju na rukama.",steps:["Kreni iz položaja za sklek, privuci stopala i podigni kukove visoko u obrnuto slovo V.","Šake postavi u širini ramena.","Savij laktove i spusti tjeme prema podu ispred šaka.","Potisni natrag do ispruženih ruku."],cues:["Glava ide naprijed i sa šakama tvori trokut","Stopala na kutiji čine vježbu težom"],miss:["Laktovi široko u stranu","Spuštanje kukova u običan sklek"],rx:"3 × 6–12 · odmor 90 s"},
"Cable Lateral Raise":{n:"Odručenje na sajli",eq:"Sajla",what:"Sajla drži napetost na bočnom deltoidu i na dnu pokreta, gdje je s bučicom lako.",steps:["Postavi sajlu na najnižu točku i stani bočno do nje.","Uhvati ručku daljom rukom tako da sajla prolazi ispred tijela.","Podigni ruku u stranu do visine ramena.","Polako spusti dok šaka ponovno ne prijeđe ispred tijela."],cues:["Lakat lagano savijen","Lagano se nagni od sprave za veće istezanje"],miss:["Slijeganje ramenima","Zamah trupom"],rx:"3 × 12–20 po strani · odmor 45–60 s"},
// --- Prsa ---
"Push-Up":{n:"Sklek",eq:"Vlastita težina",what:"Temeljna vježba guranja. Trenira prsa, prednje deltoide i triceps dok trup drži čvrstu plank poziciju.",steps:["Postavi šake malo šire od ramena, prsti naprijed.","Odmakni stopala unatrag tako da je tijelo ravno od glave do peta.","Spusti prsa na visinu šake od poda, laktovi oko 45° od tijela.","Odgurni pod dok ruke ne budu ispružene."],cues:["Stisni gluteuse i trbuh da kukovi ne propadnu","Laktovi tvore strelicu, ne slovo T"],miss:["Laktovi široko u stranu","Polovična ponavljanja daleko od poda","Glava pada prema podu"],rx:"3 × koliko god čistih ponavljanja možeš, stani 1–2 prije otkaza · odmor 60–90 s",scale:"Preteško? Stavi ruke na klupu. Prelagano? Podigni stopala ili zastani na dnu."},
"Barbell Bench Press":{n:"Potisak s ravne klupe (šipka)",eq:"Šipka + klupa",what:"Glavna vježba snage za prsa, uz veliku pomoć tricepsa i prednjih deltoida.",steps:["Lezi tako da su oči ispod šipke, stopala na podu, lopatice stisnute i spuštene.","Uhvati malo šire od ramena i skini šipku ispruženih ruku.","Kontrolirano spusti šipku na sredinu prsa, laktovi oko 45–70° od trupa.","Lagano dotakni, pa potisni gore i malo natrag prema stalku.","Kod teških serija koristi pomagača ili sigurnosne osigurače."],cues:["Pokušaj „saviti” šipku da uključiš široki leđni","Zabij stopala u pod"],miss:["Odbijanje šipke od prsa","Podizanje kukova s klupe","Gubitak položaja lopatica usred serije"],rx:"Snaga 4 × 4–6 · Masa 3 × 8–10 · odmor 2–3 min"},
"Incline Dumbbell Press":{n:"Potisak bučica na kosoj klupi",eq:"Bučice + klupa",what:"Prebacuje naglasak na gornji dio prsa. Bučice omogućuju dublje istezanje i izjednačuju razlike lijevo–desno.",steps:["Postavi klupu na 30–45°.","Sjedni s bučicama na bedrima i podigni ih koljenima dok liježeš.","Kreni s bučicama iznad gornjeg dijela prsa.","Spusti dok laktovi ne budu malo ispod razine klupe.","Potisni gore i lagano prema sredini bez sudaranja bučica."],cues:["Lopatice pritisnute uz klupu","Podlaktice okomite na dnu"],miss:["Prestrma klupa, pa vježba postaje potisak za ramena","Kratak opseg pokreta"],rx:"3 × 8–12 · odmor 90 s"},
"Cable Fly":{n:"Razvlačenje na sajli",eq:"Sajla",what:"Drži napetost na prsima kroz cijeli pokret i izolira pokret grljenja bez umaranja tricepsa.",steps:["Postavi obje sajle u visinu ramena, uhvati ručke i iskorači naprijed.","S lagano savijenim laktovima raširi ruke dok ne osjetiš istezanje prsa.","Spoji šake ispred prsa u širokom luku.","Stisni sekundu, pa se polako vrati."],cues:["Kut u laktu ne mijenja se, kao da grliš bačvu","Lagano se nagni naprijed iz kukova"],miss:["Savijanje laktova, pa vježba postaje potisak","Puštanje utega da naglo povuče ruke natrag"],rx:"3 × 12–15 · odmor 60 s"},
"Dumbbell Bench Press":{n:"Potisak bučica s ravne klupe",eq:"Bučice + klupa",what:"Potisak s ravne klupe s većim opsegom pokreta od šipke i manjom potrebom za pomagačem.",steps:["Sjedni na ravnu klupu s bučicama na bedrima, lezi i podigni ih koljenima.","Kreni s bučicama iznad prsa, lopatice povučene natrag.","Spusti dok laktovi nisu malo ispod razine klupe.","Potisni gore i lagano prema sredini."],cues:["Stopala čvrsto na podu, blagi luk u gornjim leđima","Podlaktice okomite"],miss:["Bučice odlaze prema licu","Nekontrolirano ispuštanje bučica na kraju"],rx:"3 × 8–12 · odmor 90 s"},
"Chest Dip":{n:"Propadanje na razboju (za prsa)",eq:"Razboj",what:"Propadanje s vlastitom težinom i nagibom naprijed koje snažno opterećuje donji dio prsa.",steps:["Osloni se na razboj ispruženih ruku.","Nagni trup naprijed oko 30° i pusti laktove lagano u stranu.","Spusti se dok ramena nisu malo ispod laktova ili dok ne osjetiš jako istezanje prsa.","Potisni se natrag do ispruženih ruku."],cues:["Ramena dolje, dalje od ušiju","Stani tamo gdje ti je ramenima ugodno"],miss:["Preduboko spuštanje s podignutim ramenima","Uspravan trup, pa posao preuzima triceps"],rx:"3 × 6–12 · odmor 2 min",scale:"Ako još ne možeš 5 čistih ponavljanja, koristi spravu za propadanja ili gumu za pomoć."},
"Machine Chest Press":{n:"Potisak za prsa na spravi",eq:"Sprava",what:"Vođeni potisak. Lako se nauči i siguran je za rad blizu otkaza bez pomagača.",steps:["Namjesti sjedalo tako da su ručke u visini sredine prsa.","Uhvati ručke i prisloni lopatice uz naslon.","Potisni naprijed dok ruke nisu gotovo ispružene.","Polako se vrati do istezanja."],cues:["Ramena ostaju povučena natrag","Ujednačen tempo, bez odbijanja"],miss:["Previsoko ili prenisko sjedalo","Ramena se na kraju zaokreću naprijed"],rx:"3 × 10–12 · odmor 90 s"},
// --- Biceps ---
"Barbell Curl":{n:"Pregib sa šipkom",eq:"Šipka / EZ šipka",what:"Klasična vježba za masu ruku. Ravna ili EZ šipka omogućuje teško opterećenje obiju ruku.",steps:["Stani sa šipkom u ispruženim rukama, dlanovi gore, šake u širini ramena.","Laktove drži uz tijelo.","Podigni šipku dok podlaktice ne budu okomite.","Stisni, pa spuštaj 2–3 sekunde do pune ekstenzije."],cues:["Miču se samo podlaktice","Stoj uspravno, gluteusi napeti"],miss:["Zamah kukovima","Nespuštanje do pune ekstenzije"],rx:"3 × 8–12 · odmor 60–90 s"},
"Hammer Curl":{n:"Čekić pregib",eq:"Bučice",what:"Neutralni hvat prebacuje rad na brachialis i brachioradialis, pa ruka postaje deblja, a podlaktica jača.",steps:["Drži bučice uz tijelo s dlanovima okrenutima prema bedrima.","Podigni bez rotacije zapešća, palčevi gore.","Stani kad bučica dođe do visine ramena.","Polako spusti."],cues:["Drži je kao čekić","Naizmjence ili obje ruke zajedno"],miss:["Povlačenje bučice preko tijela uz uvijanje","Laktovi idu naprijed"],rx:"3 × 10–12 · odmor 60 s"},
"Incline Dumbbell Curl":{n:"Pregib bučicama na kosoj klupi",eq:"Bučice + klupa",what:"Ruke vise iza tijela, pa je duga glava bicepsa istegnuta, što snažno potiče rast.",steps:["Postavi klupu na 45–60° i lezi s bučicama koje vise ravno dolje.","Okreni dlanove naprijed.","Podigni bez pomicanja laktova naprijed.","Spusti skroz do punog istezanja."],cues:["Ramena ostaju na klupi","Kontroliraj istezanje na dnu"],miss:["Preteško za istegnuti položaj","Odvajanje glave i ramena od klupe"],rx:"3 × 10–12 · odmor 60 s"},
"Chin-Up":{n:"Zgib pothvatom",eq:"Šipka za zgibove",what:"Zgib s dlanovima prema sebi. Snažno radi biceps uz široki leđni.",steps:["Objesi se na šipku s dlanovima prema sebi, šake u širini ramena.","Za početak povuci lopatice dolje.","Povuci se dok brada ne prijeđe šipku.","Kontrolirano se spusti do ispruženih ruku."],cues:["Prsa prema šipki","Potpuni visak na dnu"],miss:["Mahanje nogama","Polovična ponavljanja"],rx:"3 × 5–10 · odmor 2 min"},
"Preacher Curl":{n:"Pregib na Scott klupi",eq:"EZ šipka + Scott klupa",what:"Jastuk fiksira nadlakticu, pa nema zamaha i biceps radi sav posao.",steps:["Sjedni za Scott klupu sa stražnjom stranom nadlaktica na jastuku.","Uhvati EZ šipku pothvatom.","Podigni šipku dok podlaktice nisu gotovo okomite.","Polako spusti dok ruke nisu gotovo ispružene."],cues:["Pazuhe tik uz vrh jastuka","Sporo spuštanje"],miss:["Brzo padanje u zaključan lakat","Odvajanje laktova od jastuka"],rx:"3 × 8–12 · odmor 60–90 s"},
"Cable Curl":{n:"Pregib na sajli",eq:"Sajla",what:"Stalna napetost od početka do kraja. Dobro za završne serije s više ponavljanja.",steps:["Postavi ravnu šipku ili uže na donju sajlu.","Stani licem prema spravi, laktovi uz tijelo.","Podigni dok podlaktice ne budu okomite.","Polako spusti."],cues:["Laktovi ostaju na mjestu","Stisni na vrhu"],miss:["Zabacivanje unatrag","Laktovi idu naprijed"],rx:"3 × 12–15 · odmor 60 s"},
// --- Triceps ---
"Cable Pushdown":{n:"Potisak na sajli prema dolje",eq:"Sajla",what:"Jednostavna izolacija lateralne i medijalne glave, ugodna za laktove.",steps:["Postavi uže ili ravnu šipku na gornju sajlu.","Stani blizu, laktovi uz tijelo, podlaktice otprilike paralelne s podom.","Gurni dolje do potpuno ispruženih ruku; s užetom razdvoji krajeve.","Vrati se dok podlaktice ne prođu paralelu, laktovi mirni."],cues:["Laktovi zalijepljeni uz rebra","Blagi nagib naprijed je u redu"],miss:["Laktovi se šire i idu naprijed","Guranje ramenima i težinom tijela"],rx:"3 × 10–15 · odmor 60 s"},
"Overhead Dumbbell Extension":{n:"Ekstenzija bučice iznad glave",eq:"Bučica",what:"Ruke iznad glave istežu dugu glavu i grade dio tricepsa koji potisak na sajli propušta.",steps:["Sjedni ili stani držeći jednu bučicu objema rukama ispod gornjeg diska.","Podigni je iznad glave ispruženih ruku.","Spusti je iza glave savijajući samo laktove.","Ispruži natrag do vrha."],cues:["Laktovi gledaju naprijed, ne u stranu","Napni trbuh da se donja leđa ne izviju"],miss:["Laktovi se šire","Prekratko spuštanje"],rx:"3 × 10–12 · odmor 60–90 s"},
"Close-Grip Bench Press":{n:"Potisak uskim hvatom",eq:"Šipka + klupa",what:"Težak potisak koji prebacuje rad s prsa na triceps.",steps:["Lezi na ravnu klupu i uhvati šipku otprilike u širini ramena.","Skini šipku i spusti je na donji dio prsa, laktovi uz tijelo.","Lagano dotakni i potisni do ispruženih ruku.","Koristi pomagača ili osigurače."],cues:["Šake u širini ramena; uže opterećuje zapešća","Laktovi oko 30° od trupa"],miss:["Preuzak hvat","Laktovi široko kao u običnom potisku"],rx:"3 × 6–10 · odmor 2 min"},
"Skull Crusher":{n:"Francuski potisak (skull crusher)",eq:"EZ šipka + klupa",what:"Ekstenzija za triceps u ležećem položaju koja radi sve tri glave uz dobro istezanje.",steps:["Lezi na ravnu klupu s EZ šipkom iznad prsa, ruke ispružene.","Nagni ruke lagano natrag prema glavi.","Savijajući samo laktove spusti šipku prema čelu ili malo iza njega.","Ispruži natrag u početni položaj."],cues:["Nadlaktice ostaju mirne","Sporo spuštanje"],miss:["Laktovi se šire","Pretvaranje vježbe u potisak"],rx:"3 × 8–12 · odmor 90 s"},
"Diamond Push-Up":{n:"Dijamantni sklek",eq:"Vlastita težina",what:"Sklek s uskim položajem šaka koji velik dio rada prebacuje na triceps.",steps:["Postavi se u položaj za sklek sa šakama blizu, palčevi i kažiprsti se dodiruju.","Tijelo je ravno od glave do peta.","Spusti prsa prema šakama, laktovi uz tijelo.","Potisni natrag gore."],cues:["Laktovi idu natrag, ne u stranu","Ako zapešća bole, raširi šake malo više"],miss:["Propadanje kukova","Polovična ponavljanja"],rx:"3 × 8–15 · odmor 60–90 s"},
"Bench Dip":{n:"Propadanje uz klupu",eq:"Klupa",what:"Jednostavna vježba za triceps s vlastitom težinom koju možeš raditi bilo gdje uz klupu ili stolac.",steps:["Sjedni na rub klupe, šake pokraj kukova, prsti naprijed.","Pomakni se naprijed s klupe, noge savijene, stopala na podu.","Spusti se savijajući laktove do otprilike 90°.","Potisni se natrag do ispruženih ruku."],cues:["Leđa blizu klupe","Ispruži noge za težu varijantu"],miss:["Preduboko spuštanje koje opterećuje ramena","Laktovi široko u stranu"],rx:"3 × 10–15 · odmor 60 s"},
// --- Podlaktice ---
"Dumbbell Wrist Curl":{n:"Pregib zapešća s bučicom",eq:"Bučica",what:"Izolira fleksore zapešća s unutarnje strane podlaktice.",steps:["Sjedni i osloni podlaktice na bedra, dlanovi gore, zapešća preko koljena.","Pusti bučicu da se otkotrlja do vrhova prstiju.","Zatvori prste, pa savij zapešće gore što više možeš.","Polako spusti."],cues:["Miče se samo zapešće","Lagana težina, puno ponavljanja"],miss:["Odvajanje podlaktice od oslonca","Trzanje preteškog utega"],rx:"2–3 × 15–20 · odmor 45–60 s"},
"Reverse Curl":{n:"Pregib nathvatom",eq:"EZ šipka / šipka",what:"Pregib s dlanovima prema dolje za brachioradialis i ekstenzore zapešća. Uravnotežuje sav rad hvata.",steps:["Drži šipku s dlanovima prema dolje, šake u širini ramena.","S laktovima uz tijelo podigni šipku.","Zapešća drži ravno, u liniji s podlakticama.","Kontrolirano spusti."],cues:["Zglobovi prstiju gore cijelo vrijeme","Otprilike pola težine običnog pregiba"],miss:["Savijanje zapešća unatrag","Zamah tijelom"],rx:"3 × 10–15 · odmor 60 s"},
"Dead Hang":{n:"Visak na šipci",eq:"Šipka za zgibove",what:"Visenje na šipci gradi izdržljivost hvata i nježno rasterećuje ramena.",steps:["Uhvati šipku nathvatom u širini ramena.","Podigni stopala i visi ispruženih ruku.","Ramena drži lagano aktivnima, ne potpuno opuštenima.","Drži na vrijeme i siđi prije nego što ti popusti hvat."],cues:["Stišći šipku snažno","Diši polako"],miss:["Ljuljanje","Naglo puštanje s visine"],rx:"3 × 20–60 s · odmor 60–90 s"},
"Reverse Wrist Curl":{n:"Obrnuti pregib zapešća",eq:"Bučica",what:"Trenira ekstenzore zapešća na stražnjoj strani podlaktice, uravnotežuje rad hvata i pomaže spriječiti teniski lakat.",steps:["Sjedni s podlakticama na bedrima, dlanovi dolje, zapešća preko koljena.","Pusti bučicu da spusti nadlanicu.","Podigni nadlanicu što više možeš.","Polako spusti."],cues:["Miče se samo zapešće","Lakše nego što misliš"],miss:["Odvajanje podlaktice od bedra","Trzava ponavljanja"],rx:"2–3 × 15–20 · odmor 45 s"},
"Plate Pinch":{n:"Štipanje ploča",eq:"Utezi (ploče)",what:"Stiskanje glatkih ploča prstima trenira snagu palca i prstiju za jači hvat.",steps:["Spoji dvije ploče glatkim stranama prema van.","Uhvati ih prstima s jedne strane i palcem s druge.","Podigni ih i drži uz tijelo.","Spusti ih prije nego što hvat popusti."],cues:["Snažno stisni palcem","Postupno povećavaj veličinu ploča"],miss:["Držanje ploča za rub","Ispuštanje ploča na stopala"],rx:"3 × 20–40 s po ruci · odmor 60 s"},
"Wrist Roller":{n:"Namotavanje utega (wrist roller)",eq:"Valjak s užetom",what:"Namotavanje utega na uže snažno radi cijelu podlakticu, i fleksore i ekstenzore.",steps:["Drži valjak u visini ramena ispruženih ruku, dlanovi dolje.","Namotaj uže okrećući jednu pa drugu šaku.","Kad uteg dođe do vrha, polako ga odmotaj.","Ponovi s dlanovima gore."],cues:["Ruke ostaju ispružene i mirne","I sporo odmotavanje se računa"],miss:["Pomaganje ramenima","Puštanje utega da padne"],rx:"3 kruga gore i dolje · odmor 60–90 s"},
// --- Gornji trbuh ---
"Crunch":{n:"Trbušnjak (crunch)",eq:"Vlastita težina",what:"Osnovno savijanje kralježnice koje cilja gornji dio ravnog trbušnog mišića.",steps:["Lezi na leđa, koljena savijena, stopala na podu.","Vrhove prstiju lagano stavi iza ušiju ili prekriži ruke na prsima.","Izdahni i približi rebra zdjelici, podižući lopatice s poda.","Zadrži, pa polako spusti."],cues:["Rebra prema kukovima, ne glava prema koljenima","Šaka razmaka između brade i prsa"],miss:["Povlačenje vrata rukama","Dizanje do sjeda pomoću pregibača kuka"],rx:"3 × 15–20 · odmor 45 s"},
"Cable Crunch":{n:"Trbušnjak na sajli",eq:"Sajla",what:"Trbušnjak u klečećem položaju s vanjskim opterećenjem, pa trbuh možeš trenirati težim serijama kao i ostale mišiće.",steps:["Postavi uže na gornju sajlu i klekni licem prema njoj.","Drži uže pokraj glave.","Kukovi ostaju mirni, a ti savijaj kralježnicu prema dolje, laktovi prema bedrima.","Stisni, pa se polako vrati do izdužene kralježnice."],cues:["Kukovi ostaju iznad koljena","Zaobli kralježnicu umjesto pregiba u kuku"],miss:["Sjedanje na pete da pomakneš teret","Povlačenje rukama"],rx:"3 × 10–15 · odmor 60 s"},
"Ab Wheel Rollout":{n:"Kotačić za trbuh",eq:"Kotačić za trbuh",what:"Trbuh se bori da donja leđa ne propadnu dok se kotrljaš naprijed. Vrlo zahtjevno.",steps:["Klekni s kotačićem ispod ramena, ruke ispružene.","Napni trbuh i lagano podvuci zdjelicu.","Polako se kotrljaj naprijed koliko možeš bez propadanja donjih leđa.","Povuci se natrag trbuhom, ne kukovima."],cues:["Rebra dolje i uvučena cijelo vrijeme","Počni s kratkim kotrljanjem prema zidu"],miss:["Propadanje donjih leđa","Kukovi se pri povratku prvi dižu"],rx:"3 × 6–10 · odmor 90 s"},
"Front Plank":{n:"Plank (izdržaj na podlakticama)",eq:"Vlastita težina",what:"Statični izdržaj koji uči cijeli trup da drži kralježnicu mirnom.",steps:["Osloni se na podlaktice, laktovi ispod ramena.","Odmakni stopala natrag tako da je tijelo ravno od glave do peta.","Stisni gluteuse i povuci rebra prema kukovima.","Drži i mirno diši."],cues:["Lagano podvuci zdjelicu","Odguruj pod podlakticama"],miss:["Propadanje ili podizanje kukova","Zadržavanje daha"],rx:"3 × 20–60 s · odmor 45 s"},
"Stability Ball Crunch":{n:"Trbušnjak na pilates lopti",eq:"Pilates lopta",what:"Na lopti se kralježnica može ispružiti više nego na podu, pa trbuh radi kroz veći opseg.",steps:["Sjedni na loptu i hodaj stopalima naprijed dok donja leđa ne leže na lopti.","Pusti gornja leđa da se prebace preko lopte.","Približi rebra kukovima.","Polako se spusti natrag preko lopte."],cues:["Stopala široko za ravnotežu","Izdahni dok se savijaš"],miss:["Povlačenje vrata","Kotrljanje lopte umjesto savijanja"],rx:"3 × 12–20 · odmor 45 s"},
"Hollow Body Hold":{n:"Hollow izdržaj",eq:"Vlastita težina",what:"Gimnastički izdržaj koji gradi napetost cijelog tijela i snažan trbuh.",steps:["Lezi na leđa s rukama iznad glave i ispruženim nogama.","Pritisni donja leđa u pod.","Podigni ramena, ruke i noge malo od poda u plitki oblik banane.","Drži bez odvajanja donjih leđa."],cues:["Savij koljena ili ruke drži naprijed za lakšu varijantu","Ispruži prste stopala"],miss:["Donja leđa se odvajaju od poda","Previsoko podignute noge, pa vježba postaje laka"],rx:"3 × 15–40 s · odmor 45–60 s"},
// --- Donji trbuh ---
"Reverse Crunch":{n:"Obrnuti trbušnjak",eq:"Vlastita težina",what:"Podiže zdjelicu umjesto ramena i prebacuje naglasak na donji dio trbuha.",steps:["Lezi na leđa, kukovi i koljena savijeni pod 90°, ruke uz tijelo.","Izdahni i podigni kukove s poda, koljena prema prsima.","Podigni dok se trtica ne odvoji od poda.","Polako se vrati."],cues:["Odmotaj kralježnicu kralježak po kralježak","Ruke lagano na podu"],miss:["Zamah nogama","Snažno guranje rukama"],rx:"3 × 12–15 · odmor 45–60 s"},
"Hanging Knee Raise":{n:"Podizanje koljena u visu",eq:"Šipka za zgibove",what:"Rad nogama u visu jako opterećuje donji trbuh, a usput trenira i hvat.",steps:["Objesi se na šipku ispruženih ruku.","Napni trup da zaustaviš ljuljanje.","Podigni koljena prema prsima i na vrhu podvuci zdjelicu.","Polako spusti bez ljuljanja."],cues:["Podvlačenje zdjelice na vrhu je ono što radi trbuh","Napreduj do podizanja ispruženih nogu"],miss:["Samo dizanje bedara bez podvlačenja zdjelice (radi samo pregibače kuka)","Ljuljanje"],rx:"3 × 8–15 · odmor 60–90 s"},
"Dead Bug":{n:"Dead bug (mrtva buba)",eq:"Vlastita težina",what:"Vježba kontrole niskog intenziteta koja uči držati donja leđa ravnima dok se udovi miču. Dobra za zagrijavanje.",steps:["Lezi na leđa, ruke prema stropu, kukovi i koljena pod 90°.","Lagano pritisni donja leđa u pod.","Polako ispruži jednu ruku iza glave i suprotnu nogu tik iznad poda.","Vrati se i promijeni stranu."],cues:["Potpuno izdahni dok ispružuješ","Polako; brzina skriva pogreške"],miss:["Odvajanje donjih leđa od poda","Zadržavanje daha"],rx:"3 × 8–10 po strani · odmor 45 s"},
"Lying Leg Raise":{n:"Podizanje nogu u ležanju",eq:"Vlastita težina",what:"Spuštanje ispruženih nogu uz ravna leđa uči donji trbuh kontroli zdjelice.",steps:["Lezi na leđa, šake ispod kukova ili uz tijelo.","Podigni ispružene noge dok ne pokazuju prema stropu.","Spuštaj ih polako koliko možeš dok donja leđa ostaju na podu.","Ponovno ih podigni."],cues:["Donja leđa ostaju na podu","Savij koljena za lakšu varijantu"],miss:["Izvijanje leđa dok se noge spuštaju","Brzo puštanje nogu"],rx:"3 × 10–15 · odmor 45–60 s"},
"Hanging Leg Raise":{n:"Podizanje ispruženih nogu u visu",eq:"Šipka za zgibove",what:"Varijanta podizanja koljena s ispruženim nogama. Jedna od najtežih vježbi za donji trbuh.",steps:["Objesi se na šipku ispruženih ruku.","Napni trup da zaustaviš ljuljanje.","Podigni ispružene noge do visine kukova ili više, podvlačeći zdjelicu.","Polako spusti."],cues:["Kontroliraj spuštanje da izbjegneš ljuljanje","Ispruži prste stopala"],miss:["Zabacivanje nogu zamahom","Savijanje koljena kad se umoriš"],rx:"3 × 6–12 · odmor 90 s"},
"Mountain Climber":{n:"Penjač (mountain climber)",eq:"Vlastita težina",what:"Brza vježba za trup koja usput podiže i puls.",steps:["Kreni iz visokog planka, šake ispod ramena.","Privuci jedno koljeno prema prsima.","Brzo mijenjaj noge, kao da trčiš na mjestu.","Kukovi ostaju u ravnini cijelo vrijeme."],cues:["Ramena iznad šaka","Samo onoliko brzo koliko možeš kontrolirati"],miss:["Kukovi poskakuju gore-dolje","Ramena odlaze iza šaka"],rx:"3 × 20–40 s · odmor 45 s"},
// --- Kosi trbušni ---
"Side Plank":{n:"Bočni plank",eq:"Vlastita težina",what:"Statični izdržaj koji uči kose trbušne i bočne mišiće kuka da se odupru savijanju u stranu.",steps:["Lezi na bok, lakat ispod ramena, noge jedna na drugoj.","Podigni kukove tako da je tijelo ravno od glave do stopala.","Drži i ravnomjerno diši.","Ponovi na drugoj strani."],cues:["Odguruj pod podlakticom","Kukovi ostaju naprijed, ne zarotirani natrag"],miss:["Propadanje kukova","Rame se penje prema uhu"],rx:"3 × 20–45 s po strani · odmor 30–45 s"},
"Pallof Press":{n:"Pallof potisak",eq:"Sajla / guma",what:"Sajla te pokušava zarotirati, a kosi trbušni to sprječavaju. Izvrstan trening trupa koji štedi kralježnicu.",steps:["Postavi sajlu ili gumu u visinu prsa i stani bočno do nje.","Drži ručku na prsima objema rukama, stopala u širini ramena.","Gurni šake ravno naprijed bez okretanja trupa.","Zadrži 2 sekunde i vrati ih. Završi seriju, pa promijeni stranu."],cues:["Kukovi i ramena gledaju naprijed","Odmakni se dalje za težu varijantu"],miss:["Trup se okreće prema sajli","Izvijanje donjih leđa"],rx:"3 × 10–12 po strani · odmor 45 s"},
"Cable Woodchop":{n:"Sjeckanje na sajli (woodchop)",eq:"Sajla",what:"Trenira rotacijsku snagu, prenoseći silu dijagonalno od kukova preko trupa do ruku.",steps:["Postavi sajlu visoko, stani bočno i uhvati ručku objema rukama.","Povuci ručku dijagonalno dolje preko tijela prema suprotnom kuku.","Okreni stražnje stopalo i rotiraj kroz kukove dok sječeš.","Kontrolirano se vrati. Završi seriju, pa promijeni stranu."],cues:["Ruke ostaju gotovo ispružene; posao radi trup","Rotiraj kroz kukove i gornja leđa, ne samo donja leđa"],miss:["Savijanje ruku u veslanje","Prebrzo za kontrolirani povratak"],rx:"3 × 10–12 po strani · odmor 60 s"},
"Suitcase Carry":{n:"Nošenje kovčega (jednoručni hod)",eq:"Bučica / kettlebell",what:"Nošenje tereta u jednoj ruci. Kosi trbušni na suprotnoj strani snažno rade da ostaneš uspravan.",steps:["Podigni težak teret u jednu ruku.","Stani uspravno s ramenima u ravnini.","Polako hodaj zadanu udaljenost bez naginjanja.","Promijeni ruku i ponovi."],cues:["Hodaj kao da nosiš teret u objema rukama","Kratki, mirni koraci"],miss:["Naginjanje prema teretu ili od njega","Podizanje slobodnog ramena"],rx:"3 × 20–30 m po strani · odmor 60 s"},
"Bicycle Crunch":{n:"Bicikl trbušnjaci",eq:"Vlastita težina",what:"Trbušnjak s rotacijom koji zajedno radi kose i ravni trbušni mišić.",steps:["Lezi na leđa, šake lagano iza glave, koljena savijena pod 90°.","Podigni ramena.","Rotiraj tako da lakat ide prema suprotnom koljenu, a drugu nogu ispruži.","Mijenjaj strane polaganim pokretom kao na biciklu."],cues:["Rotiraj kroz rebra, ne samo laktom","Sporije je bolje od bržeg"],miss:["Povlačenje vrata","Žurba kroz ponavljanja"],rx:"3 × 10–15 po strani · odmor 45 s"},
"Landmine Rotation":{n:"Landmine rotacija",eq:"Šipka + landmine",what:"Pomicanje šipke u luku s jedne strane na drugu trenira kontroliranu rotaciju i otpor rotaciji.",steps:["Učvrsti jedan kraj šipke u landmine držač ili kut.","Drži slobodni kraj objema rukama u visini prsa, ruke ispružene.","Rotiraj šipku dolje prema jednom kuku, okrećući stražnje stopalo.","Vrati je preko vrha i spusti na drugu stranu."],cues:["Ruke ostaju duge","Kukovi i trup okreću se zajedno"],miss:["Uvijanje samo kroz donja leđa","Prepuštanje zamahu"],rx:"3 × 8–10 po strani · odmor 60–90 s"},
// --- Široki leđni ---
"Pull-Up":{n:"Zgib",eq:"Šipka za zgibove",what:"Mjerilo snage povlačenja gornjeg dijela tijela. Trenira široki leđni, biceps i srednji dio leđa.",steps:["Objesi se na šipku nathvatom malo širim od ramena.","Za početak povuci lopatice dolje i natrag.","Povuci se dok brada ne prijeđe šipku, laktovi prema kukovima.","Kontrolirano se spusti do ispruženih ruku."],cues:["Laktovi prema stražnjim džepovima","Noge mirne, malo ispred tijela"],miss:["Zamah ili kipping","Polovična ponavljanja bez ispružanja ruku"],rx:"3–4 × 5–10 · odmor 2 min",scale:"Još ne možeš ni jedan? Koristi elastičnu gumu ili vježbaj sporo spuštanje od 5 sekundi."},
"Lat Pulldown":{n:"Povlačenje na lat spravi",eq:"Sprava",what:"Isti pokret kao zgib, ali s podesivim opterećenjem, pa ga svatko može trenirati.",steps:["Namjesti jastuk čvrsto na bedra i uhvati šipku malo šire od ramena.","Lagano se nagni natrag, prsa gore.","Povuci šipku do gornjeg dijela prsa, laktovi dolje i natrag.","Polako pusti šipku gore dok ruke nisu ispružene, a široki leđni istegnut."],cues:["Vuci laktovima; šake su kuke","Ne puštaj da se ramena na vrhu podignu"],miss:["Jako zabacivanje i veslanje teretom","Povlačenje iza vrata"],rx:"3 × 8–12 · odmor 90 s"},
"One-Arm Dumbbell Row":{n:"Jednoručno veslanje bučicom",eq:"Bučica + klupa",what:"Veslanje jednom rukom s velikim opsegom pokreta koje trenira svaku stranu zasebno.",steps:["Stavi jednu ruku i koljeno iste strane na klupu, leđa ravna.","Drži bučicu u drugoj ruci ispružene ruke.","Povuci bučicu prema kuku, lakat blizu tijela.","Spusti dok ruka nije ispružena, a rame se istegne naprijed."],cues:["Vuci prema kuku, ne prema pazuhu, za više širokog leđnog","Trup ostaje paralelan s podom"],miss:["Rotiranje trupa za podizanje","Trzanje utega"],rx:"3 × 8–12 po strani · odmor 60–90 s"},
"Barbell Bent-Over Row":{n:"Veslanje šipkom u pretklonu",eq:"Šipka",what:"Teško veslanje za cijela leđa: široki leđni, srednji dio leđa i stražnje deltoide. Uči i držanje pretklona.",steps:["Uhvati šipku nathvatom malo širim od ramena.","Pregni se do oko 45° ili niže, ravnih leđa i mekanih koljena.","Povuci šipku do donjih rebara, laktovi natrag.","Spusti dok ruke nisu ispružene."],cues:["Trup miruje","Vuci prema pupku za više širokog leđnog"],miss:["Svakim ponavljanjem se sve više uspravljaš","Zaobljavanje leđa"],rx:"3–4 × 6–10 · odmor 2 min"},
"Seated Cable Row":{n:"Veslanje na sajli iz sjeda",eq:"Sajla",what:"Veslanje s osloncem i stalnom napetošću. Lako se nauči na svakoj razini.",steps:["Sjedni na spravu sa stopalima na podlozi i lagano savijenim koljenima.","Uhvati ručku ispruženih ruku i sjedni uspravno.","Povuci ručku do donjih rebara, stišćući lopatice.","Pusti ruke da se ispruže, a ramena da odu naprijed."],cues:["Prsa gore, bez ljuljanja","Vodi laktovima"],miss:["Ljuljanje trupom naprijed-natrag","Podizanje ramena"],rx:"3 × 10–12 · odmor 90 s"},
"Straight-Arm Pulldown":{n:"Povlačenje ispruženih ruku na sajli",eq:"Sajla",what:"Izolira široki leđni bez bicepsa. Dobro za učenje osjećaja širokog leđnog.",steps:["Postavi ravnu šipku ili uže na gornju sajlu i odmakni se.","Lagano se pregni naprijed, ruke ispružene, šipka u visini očiju.","Povuci šipku u luku do bedara, ruke ispružene.","Polako se vrati."],cues:["Ruke ostaju duge cijelo vrijeme","Zamisli da šipku guraš dolje malim prstima"],miss:["Savijanje laktova","Pomicanje trupa"],rx:"3 × 12–15 · odmor 60 s"},
// --- Donja leđa ---
"Bird Dog":{n:"Bird dog (ptica-pas)",eq:"Vlastita težina",what:"Vježba stabilnosti niskog opterećenja za stabilizatore kralježnice i gluteuse. Česta u rehabilitaciji leđa.",steps:["Postavi se na šake i koljena, šake ispod ramena, koljena ispod kukova.","Lagano napni trup.","Ispruži jednu ruku naprijed i suprotnu nogu natrag dok obje nisu u liniji s tijelom.","Zadrži 2–3 sekunde, vrati se i promijeni stranu."],cues:["Zamisli čašu vode na donjim leđima","Petu guraj natrag umjesto da je dižeš visoko"],miss:["Izvijanje leđa da noga ide više","Rotacija kukova"],rx:"3 × 8 po strani · odmor 30–45 s"},
"45° Back Extension":{n:"Hiperekstenzija na klupi od 45°",eq:"Klupa za hiperekstenzije",what:"Trenira ispravljače leđa, gluteuse i stražnju ložu kroz ekstenziju kuka i kralježnice.",steps:["Namjesti jastuk tik ispod pregiba kuka i učvrsti pete.","Prekriži ruke na prsima, tijelo ravno.","Spusti trup pregibom u kukovima dok ne osjetiš istezanje stražnje lože.","Podigni se natrag do ravne linije, ne dalje."],cues:["Stani na ravnoj liniji, bez prenaprezanja","Za napredak drži ploču"],miss:["Brzo zabacivanje i izvijanje na vrhu","Previsoko postavljen jastuk koji blokira pregib"],rx:"3 × 10–15 · odmor 60–90 s"},
"Conventional Deadlift":{n:"Mrtvo dizanje",eq:"Šipka",what:"Diže više tereta od bilo koje druge vježbe. Ispravljači drže kralježnicu krutom dok kukovi i noge guraju.",steps:["Stani tako da je sredina stopala ispod šipke, stopala u širini kukova.","Pregni se i uhvati šipku tik izvan nogu, potkoljenice dodiruju šipku.","Zategni šipku: prsa gore, leđa ravna, široki leđni napet.","Odgurni pod, drži šipku uz noge i uspravi se.","Pregibom se vrati dolje dok šipka klizi niz bedra i postavi se iznova za svako ponavljanje."],cues:["Šipka ostaje u dodiru s nogama","Kukovi i ramena dižu se zajedno"],miss:["Zaobljavanje donjih leđa","Šipka se odmiče od tijela","Jako zabacivanje na vrhu"],rx:"3–5 × 3–5 · odmor 3 min"},
"Superman":{n:"Superman",eq:"Vlastita težina",what:"Vježba na podu za ispravljače leđa i gluteuse bez ikakve opreme.",steps:["Lezi na trbuh s rukama ispruženima naprijed.","Istodobno podigni ruke, prsa i noge nekoliko centimetara od poda.","Zadrži 2–3 sekunde.","Polako spusti."],cues:["Gledaj u pod da vrat ostane neutralan","Malo podizanje je dovoljno"],miss:["Trzanje što više","Zabacivanje vrata"],rx:"3 × 10–12 · odmor 45 s"},
"Good Morning":{n:"Good morning (dobro jutro)",eq:"Šipka",what:"Pregib u kuku sa šipkom na leđima. Zajedno trenira ispravljače leđa, gluteuse i stražnju ložu.",steps:["Stavi laganu šipku na gornja leđa kao za čučanj.","Stani sa stopalima u širini kukova, koljena lagano savijena.","Gurni kukove natrag i spuštaj trup ravnih leđa.","Stani kad osjetiš jako istezanje stražnje lože i uspravi se."],cues:["Počni vrlo lagano","Kukovi natrag, prsa ponosno"],miss:["Zaobljavanje leđa","Previše savijena koljena"],rx:"3 × 8–12 · odmor 90 s"},
"Reverse Hyperextension":{n:"Obrnuta hiperekstenzija",eq:"Klupa / sprava",what:"Gornji dio tijela miruje dok se noge dižu iza tebe. Trenira donja leđa i gluteuse uz malo opterećenje kralježnice.",steps:["Lezi na trbuh na visoku klupu s kukovima na rubu i nogama koje vise.","Drži se za klupu.","Podigni ispružene noge dok nisu u liniji s tijelom.","Polako spusti."],cues:["Stisni gluteuse na vrhu","Bez zamaha"],miss:["Zabacivanje nogu iznad razine tijela","Snažno izvijanje donjih leđa"],rx:"3 × 12–15 · odmor 60 s"},
// --- Gluteusi ---
"Glute Bridge":{n:"Glute most",eq:"Vlastita težina",what:"Početna vježba ekstenzije kuka. Uči te osjetiti gluteuse i dobra je za zagrijavanje.",steps:["Lezi na leđa, koljena savijena, stopala na podu u širini kukova.","Napni trbuh i lagano podvuci zdjelicu.","Gurni kroz pete i podigni kukove dok koljena, kukovi i ramena nisu u liniji.","Stisni 2 sekunde, pa polako spusti."],cues:["Guraj kroz pete","Rebra ostaju dolje"],miss:["Izvijanje donjih leđa na vrhu","Stopala predaleko, pa rad preuzima stražnja loža"],rx:"3 × 12–20 · odmor 45–60 s"},
"Barbell Hip Thrust":{n:"Hip thrust sa šipkom",eq:"Šipka + klupa",what:"Najteža izravna vježba za gluteuse, s najvećom napetošću pri punoj ekstenziji kuka.",steps:["Sjedni s gornjim leđima uz rub klupe i šipkom preko kukova (koristi jastučić).","Stopala na podu otprilike u širini kukova, tako da su potkoljenice na vrhu okomite.","Uvuci bradu, napni trup i gurni kukove gore dok trup nije paralelan s podom.","Zadrži i stisni, pa spusti dok kukovi gotovo ne dotaknu pod."],cues:["Gledaj naprijed, ne u strop","Trup i šipka miču se kao jedan komad"],miss:["Izvijanje donjih leđa umjesto ekstenzije kukova","Guranje kroz prste"],rx:"3–4 × 8–12 · odmor 90–120 s"},
"Bulgarian Split Squat":{n:"Bugarski čučanj",eq:"Bučice + klupa",what:"Čučanj na jednoj nozi sa stražnjom nogom na klupi. Snažno radi gluteuse i kvadricepse i otkriva razlike između strana.",steps:["Stani otprilike dva koraka ispred klupe i stavi hrbat stražnjeg stopala na nju.","Drži bučice uz tijelo.","Spusti se ravno dolje dok stražnje koljeno gotovo ne dotakne pod.","Podigni se guranjem kroz prednje stopalo."],cues:["Lagano nagni trup naprijed za više gluteusa","Prednje koljeno prati prste"],miss:["Prednje stopalo preblizu, pa se peta odiže","Odguravanje stražnjom nogom"],rx:"3 × 8–12 po nozi · odmor 90 s"},
"Step-Up":{n:"Penjanje na klupu (step-up)",eq:"Bučice + kutija",what:"Vježba na jednoj nozi koja gradi gluteuse i kvadricepse i prenosi se na stube i planinarenje.",steps:["Stani ispred kutije visine koljena s bučicama u rukama.","Stavi cijelo stopalo jedne noge na kutiju.","Gurni kroz to stopalo i stani na kutiju bez odguravanja stražnjom nogom.","Polako siđi drugom nogom, tako da radna noga kontrolira spuštanje."],cues:["Lagano se nagni naprijed za više gluteusa","Cijelo stopalo na kutiji"],miss:["Odraz donjim stopalom","Previsoka kutija zbog koje se kukovi pomiču"],rx:"3 × 8–12 po nozi · odmor 90 s"},
"Kettlebell Swing":{n:"Zamah kettlebellom",eq:"Kettlebell",what:"Eksplozivni pregib u kuku koji istodobno gradi snagu gluteusa i kondiciju.",steps:["Stani sa stopalima malo širim od kukova, kettlebell na podu ispred tebe.","Pregni se i zabaci kettlebell natrag između nogu.","Snažno gurni kukove naprijed tako da kettlebell odleti do visine prsa.","Pusti ga da padne natrag i ponovno se pregni da ga primiš."],cues:["Posao rade kukovi; ruke su samo užad","Uspravi se i stisni gluteuse na vrhu"],miss:["Čučanj umjesto pregiba","Podizanje kettlebella rukama"],rx:"4–5 × 10–20 · odmor 60–90 s"},
"Banded Lateral Walk":{n:"Bočni hod s gumom",eq:"Elastična guma",what:"Koraci u stranu protiv gume ciljaju gluteus medius, koji stabilizira kuk i koljeno.",steps:["Postavi mini gumu tik iznad koljena ili oko gležnjeva.","Spusti se u četvrt čučnja.","Korakni u stranu održavajući napetost gume.","Napravi zadani broj koraka, pa se vrati na drugu stranu."],cues:["Prsti gledaju naprijed","Ostani nisko cijelo vrijeme"],miss:["Stopala se spajaju pa guma popusti","Ljuljanje gornjim dijelom tijela"],rx:"3 × 10–15 koraka u svaku stranu · odmor 45 s"},
// --- Kvadricepsi ---
"Goblet Squat":{n:"Goblet čučanj",eq:"Bučica / kettlebell",what:"Najbolji način da naučiš čučanj. Teret ispred tijela drži trup uspravnim i u ravnoteži.",steps:["Drži bučicu okomito uz prsa, stopala malo šire od kukova, prsti lagano van.","Napni trup i sjedni između peta, koljena guraju van iznad prstiju.","Spusti se dok bedra nisu barem paralelna s podom, laktovi unutar koljena.","Gurni kroz cijelo stopalo do stava."],cues:["Prsa ponosno, laktovi dolje","Težina na cijelom stopalu, ne na prstima"],miss:["Pete se odižu","Koljena padaju prema unutra"],rx:"3 × 10–12 · odmor 90 s"},
"Barbell Back Squat":{n:"Stražnji čučanj sa šipkom",eq:"Šipka + stalak",what:"Temeljna vježba snage donjeg dijela tijela. Trenira kvadricepse, gluteuse i aduktore dok cijeli trup stabilizira.",steps:["Stavi šipku na gornji trapez, čvrsto je uhvati, laktovi dolje.","Skini šipku, odmakni se, stopala u širini ramena, prsti lagano van.","Duboko udahni i napni trup.","Čučni dok kukovi nisu u razini koljena ili niže, koljena prate prste.","Gurni gore tako da se prsa i kukovi dižu zajedno. Uvijek postavi sigurnosne osigurače."],cues:["Razmakni pod stopalima","Udahni i napni se prije svakog ponavljanja"],miss:["Koljena padaju prema unutra na putu gore","Kukovi se dižu prvi","Zaobljavanje donjih leđa na dnu"],rx:"Snaga 4 × 4–6 · Masa 3 × 8–10 · odmor 2–3 min"},
"Leg Press":{n:"Nožni potisak",eq:"Sprava",what:"Težak rad za kvadricepse bez potrebe za ravnotežom i bez opterećenja kralježnice.",steps:["Sjedni s leđima ravno na naslonu, stopala u širini ramena na sredini platforme.","Otpusti osigurače i spuštaj platformu dok koljena ne dođu do oko 90° ili dublje.","Potisni natrag bez naglog zaključavanja koljena.","Na kraju ponovno uključi osigurače."],cues:["Niže postavljena stopala = više kvadricepsa","Donja leđa ostaju pritisnuta uz sjedalo"],miss:["Kukovi se na dnu odvajaju od sjedala","Naglo zaključavanje koljena"],rx:"3 × 10–15 · odmor 90–120 s"},
"Walking Lunge":{n:"Iskoraci u hodu",eq:"Bučice / vlastita težina",what:"Naizmjenični iskoraci naprijed koji grade snagu nogu, ravnotežu i izdržljivost.",steps:["Stani uspravno, s bučicama uz tijelo ako koristiš teret.","Iskorači naprijed i spusti se dok stražnje koljeno gotovo ne dotakne pod.","Gurni kroz prednje stopalo i dovedi stražnju nogu naprijed u sljedeći korak.","Nastavi mijenjati noge."],cues:["Trup uspravan","Prednje koljeno prati prste"],miss:["Prekratki koraci, pa se prednja peta odiže","Prednje koljeno pada prema unutra"],rx:"3 × 10–12 po nozi · odmor 90 s"},
"Leg Extension":{n:"Ekstenzija nogu na spravi",eq:"Sprava",what:"Jedina uobičajena vježba koja izolira kvadricepse, uključujući rectus femoris.",steps:["Sjedni s leđima uz naslon i valjkom na donjem dijelu potkoljenica.","Poravnaj koljena s osovinom sprave.","Potpuno ispruži noge i stisni.","Polako spusti."],cues:["Zadrži jednu sekundu na vrhu","Drži ručke da kukovi ostanu dolje"],miss:["Zamah teretom","Kukovi se odižu sa sjedala"],rx:"3 × 12–15 · odmor 60 s"},
"Front Squat":{n:"Prednji čučanj",eq:"Šipka + stalak",what:"Čučanj sa šipkom na prednjem dijelu ramena. Trup ostaje uspravniji, a kvadricepsi rade jače nego u stražnjem čučnju.",steps:["Stavi šipku na prednje deltoide blizu vrata, laktovi visoko.","Koristi olimpijski hvat ili prekrižene ruke.","Čučni, držeći laktove gore i trup uspravnim.","Gurni gore kroz cijelo stopalo."],cues:["Laktovi gore cijelo vrijeme","Koljena smiju ići naprijed preko prstiju"],miss:["Laktovi padaju pa se šipka kotrlja naprijed","Zaobljavanje gornjih leđa"],rx:"4 × 4–6 ili 3 × 6–8 · odmor 2–3 min"},
// --- Aduktori ---
"Copenhagen Plank":{n:"Kopenhaški plank",eq:"Vlastita težina + klupa",what:"Bočni plank s gornjom nogom na klupi. Istraživanja ga dobro podupiru za smanjenje ozljeda prepona kod sportaša.",steps:["Lezi na bok pokraj klupe, podlaktica na podu.","Stavi unutarnju stranu gornjeg koljena (lakše) ili gležnja (teže) na klupu.","Podigni kukove tako da tijelo bude u ravnoj liniji.","Drži, pa promijeni stranu."],cues:["Pritisni gornju nogu u klupu","Počni s varijantom na koljenu"],miss:["Propadanje kukova","Okretanje prsa prema podu"],rx:"3 × 15–30 s po strani · odmor 60 s"},
"Sumo Squat":{n:"Sumo čučanj",eq:"Bučica",what:"Čučanj širokim stavom koji opterećuje aduktore u istegnutom položaju.",steps:["Stani sa stopalima široko, prsti okrenuti van 30–45°.","Drži jednu bučicu za kraj između nogu.","Sjedni ravno dolje, gurajući koljena van preko prstiju.","Uspravi se stišćući noge prema sredini."],cues:["Trup ostaje uspravan","Koljena u liniji s prstima"],miss:["Koljena padaju prema unutra","Toliko širok stav da koljena ne mogu pratiti prste"],rx:"3 × 10–12 · odmor 90 s"},
"Hip Adduction Machine":{n:"Sprava za aduktore",eq:"Sprava",what:"Izravna izolacija unutarnje strane bedra uz lako podesivo opterećenje.",steps:["Sjedni s leđima uz naslon, unutarnja strana koljena uz jastučiće.","Postavi početnu širinu koja daje ugodno istezanje.","Stisni noge dok se jastučići ne spoje.","Polako se vrati do istezanja."],cues:["Sjedi uspravno bez ljuljanja","Kontroliraj fazu istezanja"],miss:["Opseg veći od tvoje pokretljivosti","Odbijanje iz istezanja"],rx:"3 × 12–15 · odmor 60 s"},
"Cossack Squat":{n:"Kozački čučanj",eq:"Vlastita težina / kettlebell",what:"Dubok čučanj s jedne strane na drugu koji gradi snagu aduktora i pokretljivost kukova.",steps:["Stani s vrlo širokim stavom, prsti lagano van.","Prebaci težinu na jednu stranu i duboko čučni na toj nozi.","Druga noga ostaje ispružena, prsti gledaju gore.","Gurni se natrag u sredinu i promijeni stranu."],cues:["Peta savijene noge ostaje na podu","Teret ispred tijela pomaže ravnoteži"],miss:["Zaobljavanje leđa da bi išao niže","Odizanje pete"],rx:"3 × 6–8 po strani · odmor 60–90 s"},
"Side-Lying Hip Adduction":{n:"Primicanje noge u bočnom ležanju",eq:"Vlastita težina",what:"Jednostavna vježba na podu koja podiže donju nogu pomoću unutarnje strane bedra.",steps:["Lezi na bok i prebaci gornju nogu preko, stopalo na podu ispred donjeg koljena.","Donja noga ostaje ispružena.","Podigni donju nogu što više možeš.","Polako spusti. Završi seriju, pa promijeni stranu."],cues:["Prsti gledaju naprijed, ne gore","Polako i kontrolirano"],miss:["Prevrtanje unatrag","Zamah nogom"],rx:"2–3 × 15–20 po strani · odmor 30–45 s"},
"Cable Hip Adduction":{n:"Primicanje noge na sajli",eq:"Sajla + manžeta za gležanj",what:"Primicanje noge u stojećem položaju uz stalnu napetost sajle i pun opseg pokreta.",steps:["Pričvrsti manžetu na donju sajlu i stani bočno, s manžetom na nozi bližoj spravi.","Drži se za spravu radi ravnoteže.","Povuci nogu preko i ispred stajne noge.","Polako se vrati do istezanja."],cues:["Stoj uspravno bez naginjanja","Pokret samo u kuku"],miss:["Korištenje zamaha","Jako savijanje radnog koljena"],rx:"3 × 12–15 po strani · odmor 45 s"},
// --- Stražnja loža ---
"Romanian Deadlift":{n:"Rumunjsko mrtvo dizanje",eq:"Šipka",what:"Pregib u kuku koji opterećuje stražnju ložu u dugom, istegnutom položaju.",steps:["Stani sa šipkom u visini kukova, nathvat, koljena lagano savijena.","Gurni kukove natrag i spuštaj šipku niz prednju stranu bedara.","Leđa ravna; stani kad osjetiš jako istezanje stražnje lože, često tik ispod koljena.","Gurni kukove naprijed i uspravi se."],cues:["Kukovi idu natrag, ne dolje","Šipka ostaje blizu nogu"],miss:["Sve više savijaš koljena dok ne postane čučanj","Zaobljavanje leđa da bi išao niže"],rx:"3 × 8–10 · odmor 2 min"},
"Lying Leg Curl":{n:"Pregib nogu u ležanju",eq:"Sprava",what:"Izolira savijanje koljena, posao stražnje lože koji vježbe pregiba u kuku propuštaju.",steps:["Lezi na trbuh s valjkom tik iznad peta i koljenima tik izvan jastuka.","Uhvati ručke i pritisni kukove u klupu.","Privuci pete prema gluteusima.","Polako spusti do gotovo ispruženih nogu."],cues:["Kukovi ostaju dolje","Spuštanje 3 sekunde"],miss:["Odizanje kukova za varanje","Djelomičan opseg"],rx:"3 × 10–15 · odmor 60–90 s"},
"Nordic Hamstring Curl":{n:"Nordijski pregib",eq:"Vlastita težina + oslonac",what:"Vrlo zahtjevna vježba samo za fazu spuštanja. Snažni dokazi da smanjuje istegnuća stražnje lože u sportu.",steps:["Klekni na podlogu s gležnjevima učvršćenima (partner ili šipka).","Tijelo ravno od koljena do glave, kukovi ispruženi.","Spuštaj se naprijed što sporije možeš, odupirući se stražnjom ložom.","Dočekaj se rukama, nježno se odgurni gore i ponovi."],cues:["Kukovi zaključani; ne pregibaj se u struku","Počni s malim volumenom i očekuj upalu mišića"],miss:["Pregib u kukovima","Brz pad bez kontrole"],rx:"2–3 × 3–6 · odmor 2 min"},
"Seated Leg Curl":{n:"Pregib nogu u sjedu",eq:"Sprava",what:"U sjedećem položaju stražnja loža ostaje istegnuta u kuku, a istraživanja sugeriraju da to gradi više mišića od pregiba u ležanju.",steps:["Sjedni i namjesti naslon tako da su koljena u ravnini s osovinom.","Čvrsto zaključaj jastuk za bedra.","Povuci pete dolje i natrag što više možeš.","Polako se vrati do gotovo ispruženih nogu."],cues:["Lagano se nagni naprijed za veće istezanje","Sporo spuštanje"],miss:["Prelabavo namješten jastuk za bedra","Djelomičan opseg"],rx:"3 × 10–15 · odmor 60–90 s"},
"Single-Leg Romanian Deadlift":{n:"Rumunjsko mrtvo dizanje na jednoj nozi",eq:"Bučica / kettlebell",what:"Pregib na jednoj nozi koji zajedno trenira stražnju ložu, gluteuse i ravnotežu.",steps:["Stani na jednu nogu s bučicom u suprotnoj ruci.","Pregni se u kuku, a slobodnu nogu ispruži ravno iza sebe.","Spuštaj se dok trup nije gotovo paralelan ili dok ne osjetiš jako istezanje.","Vrati se u stav."],cues:["Kukovi ostaju paralelni s podom","Stajno koljeno lagano savijeno"],miss:["Kuk stražnje noge otvara se u stranu","Zaobljavanje leđa"],rx:"3 × 8–10 po nozi · odmor 90 s"},
"Stability Ball Leg Curl":{n:"Pregib nogu na pilates lopti",eq:"Pilates lopta",what:"Most i pregib na lopti. Trenira oba posla stražnje lože: ekstenziju kuka i savijanje koljena.",steps:["Lezi na leđa s petama na pilates lopti.","Podigni kukove u most.","Savijanjem koljena privuci loptu k sebi, kukovi ostaju gore.","Polako je otkotrljaj natrag."],cues:["Kukovi visoko cijelo vrijeme","Napreduj do jedne noge"],miss:["Kukovi padaju dok privlačiš loptu","Žurba kroz ponavljanja"],rx:"3 × 8–12 · odmor 60–90 s"},
// --- Listovi ---
"Standing Calf Raise":{n:"Podizanje na prste u stojećem položaju",eq:"Stepenica / sprava",what:"Podizanje s ispruženim koljenima koje cilja gastrocnemius, vidljivi gornji dio lista.",steps:["Stani prednjim dijelom stopala na stepenicu, pete vise.","Spusti pete dok ne osjetiš duboko istezanje.","Podigni se na prste što više možeš.","Zadrži na vrhu i na dnu."],cues:["Zadrži sekundu u istezanju da ukloniš odbijanje","Koljena ispružena, ali ne zaključana"],miss:["Brzo odbijanje","Premali opseg"],rx:"3–4 × 10–15 · odmor 60 s"},
"Seated Calf Raise":{n:"Podizanje na prste u sjedu",eq:"Sprava",what:"Podizanje sa savijenim koljenom prebacuje rad na soleus, koji je jako važan za trčanje.",steps:["Sjedni s jastukom na donjem dijelu bedara i prednjim dijelom stopala na platformi.","Otpusti osigurač i spusti pete do punog istezanja.","Podigni se što više možeš.","Polako spusti."],cues:["Pun opseg svako ponavljanje","Guraj kroz palac"],miss:["Ljuljanje trupom","Preteško za pun opseg"],rx:"3 × 12–20 · odmor 60 s"},
"Tibialis Raise":{n:"Podizanje prstiju (tibialis)",eq:"Vlastita težina + zid",what:"Podizanje prstiju uz težinu tijela jača prednju stranu potkoljenice.",steps:["Nasloni leđa na zid s petama 30–60 cm od njega.","Noge drži ispruženima.","Podigni prste što više prema potkoljenicama.","Polako spusti bez lupanja o pod."],cues:["Dalje od zida = teže","Polako i kontrolirano"],miss:["Savijanje koljena","Žurba kroz ponavljanja"],rx:"2–3 × 15–25 · odmor 45 s"},
"Single-Leg Calf Raise":{n:"Podizanje na prste na jednoj nozi",eq:"Stepenica / bučica",what:"Udvostručuje opterećenje svakog lista bez sprave i izjednačuje razlike između strana.",steps:["Stani jednom nogom na stepenicu, peta visi, drži se za zid radi ravnoteže.","Spusti petu do dubokog istezanja.","Podigni se na prednji dio stopala što više možeš.","Zadrži, pa spusti. Završi seriju, pa promijeni nogu."],cues:["Za napredak drži bučicu u ruci radne strane","Pun opseg svako ponavljanje"],miss:["Odbijanje","Prevrtanje na vanjski rub stopala"],rx:"3 × 10–15 po nozi · odmor 45–60 s"},
"Leg Press Calf Raise":{n:"Podizanje na prste na nožnom potisku",eq:"Sprava za nožni potisak",what:"Omogućuje teško opterećenje listova u sjedećem položaju s osloncem.",steps:["Sjedni u nožni potisak i stavi prednji dio stopala na donji rub platforme.","Ispruži noge; ako sprava dopušta, ostavi osigurače uključene.","Ispruži stopala i odgurni platformu.","Pusti pete natrag prema sebi do punog istezanja."],cues:["Koljena ispružena, ali ne zaključana","Polako i kontrolirano"],miss:["Stopala klize s platforme","Pomaganje savijanjem koljena"],rx:"3 × 12–20 · odmor 60 s"},
"Jump Rope":{n:"Preskakanje užeta",eq:"Uže za preskakanje",what:"Niski, brzi skokovi treniraju elastičnost i izdržljivost listova, stabilnost gležnja i koordinaciju.",steps:["Drži ručke u visini kukova, uže iza sebe.","Okreći uže zapešćima, ne rukama.","Skači tek toliko da uže prođe, mekano doskakujući na prednji dio stopala.","Drži stalan ritam."],cues:["Mali skokovi, tihi doskoci","Laktovi uz tijelo"],miss:["Previsoki skokovi","Doskok na cijelo stopalo ili na pete"],rx:"5–10 krugova po 30–60 s · odmor 30–60 s"}
}
